(() => {
'use strict';
const $=id=>document.getElementById(id), W=9,H=11,KEY='beyond-chapel-v1';
const INTRO='Дождь стихает у порога часовни. За дубовой дверью слышен скрежет. «Колокол исчез, но кто-то всё ещё служит здесь», — шепчет Мира. Найдите реликвию и вернитесь к южному входу.';
let state,selected=null,path=[],diceTimer,focus={x:2,y:8};
function random(n){const a=new Uint32Array(1),limit=4294967296-4294967296%n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n+1}
function fresh(){return {version:1,hero:{id:'hero',name:'Эльдар',x:2,y:8,hp:24,max:24,kind:'ranger',facing:'down'},allies:[{id:'mira',name:'Мира',x:1,y:9,hp:18,max:18,kind:'mage',facing:'down'},{id:'bor',name:'Бор',x:3,y:9,hp:28,max:28,kind:'guard',facing:'down'}],enemies:[{id:'e1',name:'Страж',x:6,y:2,hp:13,max:13,kind:'enemy',facing:'down'},{id:'e2',name:'Костяной дозорный',x:7,y:4,hp:11,max:11,kind:'enemy',facing:'down'}],door:false,noise:false,chest:false,relic:false,complete:false,defeated:false,combat:false,round:1,move:5,acted:false,potions:2,gold:0,xp:0,level:1,logs:[INTRO],narrative:INTRO,draft:'',seed:random(99999)}}
try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved&&saved.version===1&&saved.hero&&Array.isArray(saved.logs)?saved:fresh()}catch{state=fresh()}
for(const e of [state.hero,...(state.allies||[]),...(state.enemies||[])])e.facing=e.facing||'down';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('save-status').textContent='✓ На этом устройстве'}catch{$('save-status').textContent='Сохранение недоступно'}}
function tell(text){state.narrative=text;state.logs.push(text);if(state.logs.length>120)state.logs.shift()}
function wall(x,y){return x<=0||x>=8||y<=0||y>=10||(y===5&&x!==4)||(x===3&&y===3)||(x===6&&y===7)}
function object(x,y){if(x===4&&y===5&&!state.door)return'door';if(x===2&&y===2&&!state.chest)return'chest';if(x===6&&y===1&&!state.relic)return'altar';if(x===4&&y===9)return'exit';return null}
function entities(){return [state.hero,...state.allies,...state.enemies].filter(e=>e.hp>0)}
function occupant(x,y){return entities().find(e=>e.x===x&&e.y===y)}
function blocked(x,y){return wall(x,y)||['door','chest','altar'].includes(object(x,y))}
function dist(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}
function visible(x,y){return state.door||y>=5}
function route(start,target,occupied=true){const mover=occupant(start.x,start.y);const q=[[start]],seen=new Set([start.x+','+start.y]);while(q.length){const p=q.shift(),v=p[p.length-1];if(v.x===target.x&&v.y===target.y)return p.slice(1);for(const [dx,dy]of[[0,-1],[1,0],[0,1],[-1,0]]){const n={x:v.x+dx,y:v.y+dy},k=n.x+','+n.y;const other=occupant(n.x,n.y);const occupiedBlock=occupied&&other&&((n.x===target.x&&n.y===target.y)||((other.kind==='enemy')!==(mover?.kind==='enemy')));if(seen.has(k)||blocked(n.x,n.y)||occupiedBlock)continue;seen.add(k);q.push([...p,n])}}return null}
function line(a,b){let x=a.x,y=a.y,dx=Math.abs(b.x-x),sx=x<b.x?1:-1,dy=-Math.abs(b.y-y),sy=y<b.y?1:-1,err=dx+dy;while(x!==b.x||y!==b.y){let e=2*err;if(e>=dy){err+=dy;x+=sx}if(e<=dx){err+=dx;y+=sy}if(blocked(x,y))return false}return true}
function cardinal(a,b){return a.x===b.x||a.y===b.y}
function faceToward(a,b){if(Math.abs(b.x-a.x)>=Math.abs(b.y-a.y))a.facing=b.x<a.x?'left':'right';else a.facing=b.y<a.y?'up':'down'}
function faceStep(a,b){if(b.x!==a.x)a.facing=b.x<a.x?'left':'right';else if(b.y!==a.y)a.facing=b.y<a.y?'up':'down'}
function covered(e){return [[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>wall(e.x+dx,e.y+dy))}
function roll(){const n=random(20);$('dice-value').textContent=n;const el=$('dice');el.hidden=true;void el.offsetWidth;el.hidden=false;clearTimeout(diceTimer);diceTimer=setTimeout(()=>el.hidden=true,2300);return n}
function act(label,fn,extra=''){const b=document.createElement('button');b.textContent=label;b.className=extra;b.onclick=fn;$('actions').append(b)}
function select(x,y){if(x<0||x>=W||y<0||y>=H)return;selected={x,y};path=[];if(!blocked(x,y)&&!occupant(x,y)&&visible(x,y))path=route(state.hero,selected)||[];render()}
function move(){if(!path.length||state.complete||state.defeated)return;if(state.combat&&path.length>state.move)return;const p=path[path.length-1],steps=path.length,routePath=[{x:state.hero.x,y:state.hero.y},...path];faceStep(state.hero,routePath[1]);art.travel('hero',routePath);state.hero.x=p.x;state.hero.y=p.y;if(state.combat)state.move-=steps;else follow();selected=null;path=[];save();render()}
function follow(){for(const ally of state.allies.filter(a=>a.hp>0)){if(dist(ally,state.hero)<=2)continue;const options=[[0,1],[-1,0],[1,0],[0,-1]].map(([dx,dy])=>({x:state.hero.x+dx,y:state.hero.y+dy})).filter(p=>!blocked(p.x,p.y)&&!occupant(p.x,p.y));let best=null;for(const p of options){const r=route(ally,p);if(r&&(!best||r.length<best.length))best=r}if(best&&best.length){const stops=best.slice(0,3).filter(p=>!occupant(p.x,p.y));if(stops.length){const p=stops[stops.length-1];faceStep(ally,best[0]);ally.x=p.x;ally.y=p.y}}}}
function openDoor(force){if(dist(state.hero,{x:4,y:5})>1||state.door||state.combat)return;const n=roll(),bonus=force?2:4,dc=force?10:12;if(n+bonus>=dc){state.door=true;state.combat=true;state.move=5;state.acted=false;tell(`d20: ${n} + ${bonus} = ${n+bonus} против ${dc}. Дверь открывается. Два костяных стража оборачиваются к свету. Мира поднимает посох. Начинается бой — ваш ход.`)}else{state.noise=true;tell(`d20: ${n} + ${bonus} = ${n+bonus} против ${dc}. ${force?'Дубовая дверь выдерживает удар.':'Отмычка соскальзывает.'} За дверью звенит металл. Можно попробовать снова или выбить дверь.`)}selected=null;save();render()}
function hit(attacker,target,bonus,sides,flat,cover=false){faceToward(attacker,target);const n=attacker.id==='hero'?roll():random(20),ac=target.kind==='enemy'?11:12,def=ac+(cover?2:0),success=n===20||(n!==1&&n+bonus>=def);let damage=0;if(success){damage=random(sides)+flat+(n===20?random(sides):0);target.hp=Math.max(0,target.hp-damage)}return `${attacker.name}: d20 ${n} + ${bonus} против ${def}${cover?' (укрытие)':''} — ${success?`${n===20?'критический удар, ':''}${damage} урона по ${target.name}`:'промах'}.`}
function checkBattle(){if(state.hero.hp<=0){state.defeated=true;state.combat=false;tell('Вы падаете на каменные плиты. Экспедиция завершилась поражением. Можно начать новую попытку через меню.');return true}if(state.enemies.every(e=>e.hp<=0)){state.combat=false;state.xp=60;tell('Стражи рассыпаются. В часовне становится тихо. +60 опыта. На северном алтаре лежит реликвия. Заберите её и вернитесь к южному входу.');return true}return false}
function attack(enemy){if(!state.combat||state.acted||enemy.hp<=0||dist(state.hero,enemy)>5||!cardinal(state.hero,enemy)||!line(state.hero,enemy))return;const melee=dist(state.hero,enemy)===1;tell(hit(state.hero,enemy,4,melee?8:6,2,!melee&&covered(enemy)));state.acted=true;checkBattle();selected=null;save();render()}
function approach(e,target,steps){for(let i=0;i<steps;i++){if(dist(e,target)<=1){faceToward(e,target);return}let best=null;for(const [dx,dy]of[[0,1],[1,0],[0,-1],[-1,0]]){const p={x:target.x+dx,y:target.y+dy};if(blocked(p.x,p.y)||occupant(p.x,p.y))continue;const r=route(e,p);if(r&&r.length&&(!best||r.length<best.length))best=r}if(!best)return;const step=best.find(p=>!occupant(p.x,p.y));if(!step)return;const cost=best.indexOf(step)+1;if(i+cost>steps)return;faceStep(e,step);e.x=step.x;e.y=step.y;i+=cost-1}if(dist(e,target)<=1)faceToward(e,target)}
function endTurn(){if(!state.combat||state.defeated)return;const log=[];for(const ally of state.allies.filter(a=>a.hp>0)){const enemy=state.enemies.filter(e=>e.hp>0).sort((a,b)=>dist(ally,a)-dist(ally,b))[0];if(!enemy)break;if(ally.kind==='mage'&&(dist(ally,enemy)>5||!line(ally,enemy))||ally.kind==='guard'&&dist(ally,enemy)>1)approach(ally,enemy,3);if(cardinal(ally,enemy)&&dist(ally,enemy)<=(ally.kind==='mage'?5:1)&&line(ally,enemy))log.push(hit(ally,enemy,3,6,1,ally.kind==='mage'&&covered(enemy)));else log.push(`${ally.name} занимает позицию.`)}if(log.length)tell(log.join(' '));if(checkBattle()){save();render();return}log.length=0;for(const e of state.enemies.filter(e=>e.hp>0)){const target=[state.hero,...state.allies].filter(a=>a.hp>0).sort((a,b)=>dist(e,a)-dist(e,b))[0];if(!target)break;approach(e,target,3);if(dist(e,target)<=1)log.push(hit(e,target,2,4,1));else log.push(`${e.name} приближается.`)}if(log.length)tell(log.join(' '));if(!checkBattle()){state.round++;state.move=5;state.acted=false}selected=null;path=[];save();render()}
function interact(type){if(!selected||dist(state.hero,selected)>1||state.combat||state.defeated||state.complete)return;if(type==='chest'){state.chest=true;state.gold+=15;state.potions++;tell('В сундуке сохранились 15 монет и лечебное зелье. На обрывке письма: «Колокол забрали на север. Не верьте настоятелю». Зацепка записана в хронику.')}if(type==='altar'){state.relic=true;tell('Вы поднимаете серебряный язычок исчезнувшего колокола. На металле вырезано имя: «Эллен». Мира узнаёт его, но отводит взгляд. Возвращайтесь к южному входу.')}if(type==='exit'){if(!state.relic){tell('Пока рано уходить: реликвия всё ещё в часовне. Северный проход закрыт дубовой дверью.')}else{state.complete=true;state.xp=100;state.level=2;state.gold+=30;state.hero.max=30;state.hero.hp=30;tell('Вы выходите под утреннее небо. Реликвия найдена. +30 монет, уровень 2. Мира тихо произносит: «Эллен была моей сестрой». Первая глава завершена. Продолжение истории появится в следующей версии.')}}selected=null;save();render()}
function potion(){if(!state.potions||state.hero.hp>=state.hero.max||state.defeated||state.complete||(state.combat&&state.acted))return;const restored=Math.min(10,state.hero.max-state.hero.hp);state.hero.hp+=restored;state.potions--;if(state.combat)state.acted=true;tell(`Вы выпиваете зелье: +${restored} здоровья.${state.combat?' Действие потрачено.':''}`);save();render();inventory()}
function actionPanel(){const box=$('actions');box.replaceChildren();let text='Нажмите на свободную клетку, чтобы проложить путь.';if(state.complete)text='Приключение завершено. Уровень 2 — ваша первая история сохранена.';else if(state.defeated)text='Отряд потерпел поражение. Новая попытка доступна в меню.';else if(selected){const o=object(selected.x,selected.y),e=occupant(selected.x,selected.y),near=dist(state.hero,selected)<=1;if(!visible(selected.x,selected.y)){text='За закрытой дверью. Сначала откройте проход.'}else if(e){text=`${e.name} · ${e.hp}/${e.max} здоровья`;if(e.kind==='enemy'&&state.combat){if(state.acted)text+=' · действие уже потрачено';else if(!cardinal(state.hero,e))text+=' · атака только по 4 сторонам';else if(dist(state.hero,e)>5)text+=' · вне дальности';else if(!line(state.hero,e))text+=' · нет прямой видимости';else act(dist(state.hero,e)===1?'Ударить мечом · d20':'Выстрелить · d20',()=>attack(e))}}else if(o==='door'){text=near?'Дубовая дверь · ловкость 12 или сила 10':'Подойдите к двери вплотную.';if(near&&!state.combat){act('Вскрыть · d20 +4',()=>openDoor(false));act('Выбить · d20 +2',()=>openDoor(true))}}else if(o==='altar'||o==='chest'){text=state.combat?'Сначала завершите бой.':near?(o==='altar'?'Реликвия на алтаре':'Старый дорожный сундук'):'Подойдите к объекту вплотную.';if(near&&!state.combat)act(o==='altar'?'Забрать реликвию':'Открыть сундук',()=>interact(o))}else if(o==='exit'&&near){text='Южный вход в часовню';if(!state.combat)act('Покинуть часовню',()=>interact('exit'))}else if(wall(selected.x,selected.y))text='Каменная кладка · непроходимо';else if(path.length){text=`Маршрут: ${path.length} кл.${state.combat?` · доступно ${state.move}`:''}`;if(!state.combat||path.length<=state.move)act(`Идти · ${path.length} кл.`,move);else text+=' · слишком далеко';}else text='Проход занят или недоступен.'}if(!state.complete&&!state.defeated&&state.combat)act('Завершить ход',endTurn,'secondary');$('selection').textContent=text}
function render(){const ps=[state.hero,...state.allies];$('party').innerHTML=ps.map((p,i)=>`<div class="member ${i===0?'self':''}"><div class="portrait"><canvas data-portrait="${p.kind}" aria-hidden="true"></canvas></div><b>${p.name}</b><small>${p.hp}/${p.max} HP</small><div class="hp-track"><div class="hp-fill" style="width:${p.hp/p.max*100}%"></div></div></div>`).join('');$('phase').textContent=state.complete?'✧ Глава завершена':state.defeated?'◇ Поражение':state.combat?`⚔ Бой · раунд ${state.round}`:'◈ Исследование';$('movement').textContent=state.combat?`Ход: ${state.move} кл. · ${state.acted?'0':'1'} действие`:'Отряд следует за вами';$('quest').textContent=state.complete?'Реликвия спасена. Мира хранит новую тайну.':state.relic?'Вернитесь к южному входу с реликвией.':'Найдите реликвию в заброшенной часовне.';$('level').textContent=`УР. ${state.level}`;$('narrative').textContent=state.narrative;$('journal-count').textContent=state.logs.length;actionPanel();draw()}
const canvas=$('map'),art=createChapelArt(canvas);
function draw(){art.update(state,selected,path,wall,route,blocked,occupant)}
function modal(title,html){$('modal-title').textContent=title;$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function inventory(){modal('Рюкзак',`<div class="item"><span>Монеты</span><b>${state.gold}</b></div><div class="item"><span>Лечебное зелье · +10 HP</span><b>${state.potions}</b></div><div class="item"><span>Короткий лук · меч</span><span>Экипировано</span></div>${state.relic?'<div class="item"><span>Язычок колокола</span><span>Реликвия</span></div>':''}<p class="hint">В бою зелье расходует действие. Его нельзя выпить при полном здоровье.</p><button id="drink" class="primary">Выпить зелье</button>`);$('drink').disabled=!state.potions||state.hero.hp>=state.hero.max||state.defeated||state.complete||(state.combat&&state.acted);$('drink').onclick=potion}
function character(){modal('Эльдар · следопыт',`${art.characterArt('ranger')}<p>Уровень ${state.level} · Опыт ${state.xp}/100 · Здоровье ${state.hero.hp}/${state.hero.max}</p><div class="stat-grid"><div>+2<small>СИЛА</small></div><div>+4<small>ЛОВКОСТЬ</small></div><div>+1<small>МУДРОСТЬ</small></div></div><p>Лук: дальность 5 клеток, d20 +4, урон d6 +2.<br>Меч: соседняя клетка, d20 +4, урон d8 +2.</p><p>Мира — маг, дальность 5 клеток.<br>Бор — защитник, ближний бой.</p><p class="hint">Спутники действуют автоматически после вашего хода по простым правилам. Создание и смена героев появятся позже.</p>`);art.portraits()}
function help(){modal('Как играть',`<ol><li>Нажмите на свободную клетку, затем «Идти». Стены непроходимы. Через союзника можно пройти, но нельзя занять его клетку.</li><li>Подойдите к двери в центре карты вплотную. Нажмите на неё и выберите проверку.</li><li>В бою у вас 5 клеток перемещения и одно действие. Нажмите на врага для атаки.</li><li>Движение и атаки работают только по четырём сторонам: вверх, вниз, влево и вправо. Диагональные атаки запрещены.</li><li>Фигурки поворачиваются по направлению движения и разворачиваются к цели перед атакой. Враги используют те же правила.</li><li>«Завершить ход» запускает действия спутников и противников.</li><li>После боя заберите реликвию на северном алтаре. Вернитесь к отмеченному южному выходу.</li></ol><p class="hint">Стены перекрывают выстрел. Противник рядом со стеной получает +2 к защите от дальних атак — упрощённое правило укрытия этой пробы.</p><p class="hint">Броски делает криптографический генератор браузера. Серверная проверка, ИИ-ведущий и совместная игра ещё не подключены. Сохранение привязано к этому браузеру и может исчезнуть при очистке его данных.</p>`)}
$('menu').onclick=()=>{modal('Приключение',`<p>Соло · герой и два спутника</p><p>Тестовая глава «Часовня без колокола». События заданы заранее. Прогресс сохраняется в браузере после действий.</p><div class="button-row"><button class="secondary" id="menu-help">Как играть</button><button class="secondary" id="restart">Новая попытка</button></div>`);$('menu-help').onclick=help;$('restart').onclick=()=>{modal('Начать заново?',`<p>Текущая попытка и её прогресс будут заменены.</p><button class="primary" id="confirm-reset">Начать новую попытку</button>`);$('confirm-reset').onclick=()=>{state=fresh();selected=null;path=[];save();render();$('modal').close()}}};
$('journal').onclick=()=>{modal('Хроника', '<div id="entries"></div>');for(let i=state.logs.length-1;i>=0;i--){const el=document.createElement('div');el.className='journal-entry';const label=document.createElement('small');label.textContent=`СОБЫТИЕ ${i+1}`;el.append(label,document.createTextNode(state.logs[i]));$('entries').append(el)}};
$('custom').onclick=()=>{modal('Своё действие',`<p>ИИ-ведущий пока не подключён. Здесь можно сохранить задумку для сцены — она не изменит игровой мир.</p><textarea id="draft" maxlength="1000" placeholder="Например: отвлекаю стража звоном монеты…" aria-label="Задумка действия"></textarea><div class="button-row"><button class="primary" id="save-draft">Сохранить задумку</button></div>`);$('draft').value=state.draft;$('save-draft').onclick=()=>{state.draft=$('draft').value;save();$('modal').close()}};
$('nav-character').onclick=character;$('nav-inventory').onclick=inventory;$('nav-help').onclick=help;$('nav-map').onclick=()=>canvas.scrollIntoView({behavior:'smooth',block:'center'});$('close-modal').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close()}};
canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect();select(Math.floor((e.clientX-r.left)/r.width*W),Math.floor((e.clientY-r.top)/r.height*H))});canvas.addEventListener('keydown',e=>{const dirs={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};if(dirs[e.key]){e.preventDefault();focus.x=Math.max(0,Math.min(8,focus.x+dirs[e.key][0]));focus.y=Math.max(0,Math.min(10,focus.y+dirs[e.key][1]));select(focus.x,focus.y)}if(e.key==='Enter'){$('actions').querySelector('button')?.click()}});
new ResizeObserver(draw).observe(canvas);save();render();
})();
